from pathlib import Path


root = Path(__file__).resolve().parents[1]
source = (root / "app" / "page.tsx").read_text(encoding="utf-8")
start = source.index("const questions: Question[] = [")
end = source.index("\n];", start) + 3
question_js = source[start:end].replace("const questions: Question[] =", "const questions =", 1)

head = r'''<!doctype html>
<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>JLPT N2 文法009〜015 確認テスト</title>
<style>
:root{--ink:#1b2430;--muted:#667384;--paper:#f6f4ee;--card:#fffefa;--line:#dfe3e6;--red:#d64a3a;--blue:#214e76;--gold:#d7a84c}*{box-sizing:border-box}body{margin:0;color:var(--ink);font-family:Arial,"Noto Sans JP","Yu Gothic",sans-serif;background:radial-gradient(circle at 10% 0,#fff 0,transparent 30%),linear-gradient(135deg,#f8f6f0,#eef1f2);min-height:100vh}.shell{width:min(920px,calc(100% - 28px));margin:auto;padding:36px 0 56px}.start{display:grid;min-height:100vh;place-items:center}.card{background:var(--card);border:1px solid var(--line);border-radius:6px}.start-card{width:min(680px,100%);padding:54px;border-top:7px solid var(--red);box-shadow:0 24px 70px #25313d18}.kicker{color:var(--red);font-size:12px;font-weight:800;letter-spacing:.16em;margin:0 0 10px}.start h1{font-family:serif;font-size:clamp(38px,7vw,68px);letter-spacing:-.04em;margin:0}.lead{font-size:17px;color:var(--muted);margin:14px 0 32px}.facts{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line);margin:28px 0}.facts div{padding:20px;text-align:center;border-right:1px solid var(--line)}.facts div:last-child{border:0}.facts strong,.facts span{display:block}.facts strong{font-size:24px}.facts span{color:var(--muted);font-size:11px;margin-top:5px}.notice{color:var(--muted);font-size:13px}.primary,.secondary{border:0;border-radius:4px;padding:14px 22px;font-weight:800;cursor:pointer}.primary{color:#fff;background:var(--blue)}.secondary{border:1px solid var(--line);background:#fff;color:var(--ink)}.secondary:disabled{opacity:.4}.start .primary{width:100%;margin-top:18px;font-size:16px}.quiz-head,.result-head{display:flex;justify-content:space-between;align-items:center}.quiz-head strong{font-family:serif;font-size:24px}.timer{font-variant-numeric:tabular-nums;font-size:22px;font-weight:800;color:var(--blue);background:#fff;padding:12px 16px;border:1px solid var(--line)}.danger{color:var(--red)}.progress{height:4px;background:#d9dde0;margin:22px 0 28px}.progress i{display:block;height:100%;background:var(--red)}.question-card{padding:34px;min-height:460px}.question-meta,.review-top{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;font-weight:700}.question-card h1{white-space:pre-wrap;font-family:serif;font-size:clamp(23px,4vw,32px);line-height:1.75;margin:36px 0}.choices{display:grid;gap:10px}.choices button{display:flex;align-items:center;text-align:left;border:1px solid var(--line);background:#fff;padding:15px 16px;border-radius:4px;font-size:16px;cursor:pointer}.choices button.selected{border:2px solid var(--blue);background:#eef5fa;padding:14px 15px}.choices b{display:grid;place-items:center;width:28px;height:28px;margin-right:13px;background:#eef0f1;border-radius:50%;font-size:12px}.choices .selected b{background:var(--blue);color:#fff}nav{display:flex;gap:14px;align-items:center;justify-content:space-between;margin-top:18px}.dots{display:flex;gap:5px;flex-wrap:wrap;justify-content:center}.dots button{width:29px;height:29px;border:1px solid var(--line);background:#fff;color:var(--muted);border-radius:50%;font-size:11px}.dots .answered{border-color:#89a26b;color:#47632a}.dots .active{background:var(--ink);color:#fff}.result-head{background:var(--ink);color:#fff;padding:30px;border-radius:6px}.result-head h1{font-family:serif;font-size:64px;margin:0}.result-head p{color:#c5ccd3;margin:5px 0 0}.score-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0 24px}.score-grid div{background:#fff;border:1px solid var(--line);padding:18px}.score-grid span,.score-grid strong{display:block}.score-grid span{font-size:11px;color:var(--muted)}.score-grid strong{font-size:25px;margin-top:7px}.review-list{display:grid;gap:15px}.review{border-left:5px solid #69a06e;padding:28px}.review.wrong{border-left-color:var(--red)}.review.unknown,.review.unanswered{border-left-color:var(--gold)}.review-top b{color:var(--ink)}.category{font-size:12px;color:var(--red);font-weight:700;margin:22px 0 7px}.review h2{font-family:serif;font-size:21px;line-height:1.6;white-space:pre-wrap;margin:0 0 24px}.review dl{display:grid;grid-template-columns:110px 1fr;margin:0;border-top:1px solid var(--line)}.review dt,.review dd{padding:11px 0;border-bottom:1px solid var(--line);margin:0;font-size:13px;line-height:1.65}.review dt{font-weight:800;color:var(--muted)}.hidden{display:none!important}@media(max-width:640px){.start-card,.question-card{padding:26px 20px}.facts,.score-grid{grid-template-columns:1fr}.facts div{border-right:0;border-bottom:1px solid var(--line)}.dots{display:none}.review{padding:22px 18px}.review dl{grid-template-columns:1fr}.review dt{border-bottom:0;padding-bottom:2px}.review dd{padding-top:2px}}
</style></head><body><main id="app"></main><script>
'''

tail = r'''
const unknown='分からない', limit=600;
let started=false,submitted=false,current=0,elapsed=0,answers={},timer=null;
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=()=>`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(elapsed%60).padStart(2,'0')}`;
const results=()=>questions.map(q=>{const selected=answers[q.id],correct=q.choices[q.answer];return {...q,selected,correct,state:!selected?'unanswered':selected===unknown?'unknown':selected===correct?'correct':'wrong'}});
function start(){started=true;timer=setInterval(()=>{elapsed++;if(elapsed>=limit)submit();else render()},1000);render()}
function pick(v){answers[questions[current].id]=v;render()}
function go(i){current=i;render()}
function submit(){if(submitted)return;submitted=true;clearInterval(timer);render()}
function payload(){const r=results(),count=s=>r.filter(x=>x.state===s).length;return {test_id:'n2-grammar-009-015-check-20260830',test_date:'2026-08-30',title:'N2 문법 009~015 확인시험',source_class:'자체 제작',target_level:'N2',memory_timing:'강의 후 익일 확인',total_items:10,correct_items:count('correct'),wrong_items:count('wrong'),unknown_items:count('unknown'),unanswered_items:count('unanswered'),elapsed_seconds:elapsed,time_limit_seconds:limit,timed_out:elapsed>=limit,groups:Object.fromEntries(['文の文法1','文の文法2','文章の文法'].map(k=>{const a=r.filter(x=>x.kind===k);return[k,{correct:a.filter(x=>x.state==='correct').length,total:a.length}]})),attempts:r.map(x=>({item_no:x.number,question_id:x.id,item_type_id:x.kind==='文の文法1'?'grammar_form':x.kind==='文の文法2'?'sentence_composition':'text_grammar',type:x.kind,category:x.category,pattern:x.pattern,state:x.state,question:x.prompt,choices:x.choices,selected_text:x.selected??null,correct_text:x.correct,visited:Boolean(x.selected)})),review_dates:[{interval:'D+1',date:'2026-08-31'},{interval:'D+3',date:'2026-09-02'},{interval:'D+7',date:'2026-09-06'}],practice_note:'강의 후 자체 제작 확인시험. JLPT식 문법 형식이지만 공식 기출·공식 모의고사가 아니며 합격 확률로 직접 환산하지 않음.',timing_note:'開始する부터 제출까지 타이머만 기록. 해설 읽기와 다른 학습시간은 포함하지 않음.'}}
async function copyResult(){await navigator.clipboard.writeText(JSON.stringify(payload(),null,2));document.querySelector('#copy').textContent='コピーしました'}
function render(){
 if(!started){app.innerHTML=`<main class="shell start"><section class="start-card card"><p class="kicker">JLPT N2 · 文法 009〜015</p><h1>講義後確認テスト</h1><p class="lead">文の文法・文の組み立て・文章の文法</p><div class="facts"><div><strong>10</strong><span>問題</span></div><div><strong>10:00</strong><span>制限時間</span></div><div><strong>7</strong><span>文型</span></div></div><p class="notice">各問題には「分からない」があります。開始後にタイマーが動きます。</p><button class="primary" onclick="start()">開始する</button></section></main>`;return}
 if(submitted){const r=results(),count=s=>r.filter(x=>x.state===s).length,order={wrong:0,unknown:1,unanswered:2,correct:3};app.innerHTML=`<main class="shell"><header class="result-head"><div><p class="kicker">RESULT</p><h1>${count('correct')} / 10</h1><p>${time()} · 誤答 ${count('wrong')} · 分からない ${count('unknown')} · 未回答 ${count('unanswered')}</p></div><button id="copy" class="secondary" onclick="copyResult()">結果をコピー</button></header><section class="score-grid">${['文の文法1','文の文法2','文章の文法'].map(k=>{const a=r.filter(x=>x.kind===k);return `<div><span>${k}</span><strong>${a.filter(x=>x.state==='correct').length}/${a.length}</strong></div>`}).join('')}</section><section class="review-list">${r.sort((a,b)=>order[a.state]-order[b.state]).map(x=>`<article class="review card ${x.state}"><div class="review-top"><span>問題 ${x.number} · ${x.kind}</span><b>${x.state==='correct'?'正解':x.state==='wrong'?'誤答':x.state==='unknown'?'分からない':'未回答'}</b></div><p class="category">${x.category}</p><h2>${esc(x.prompt)}</h2><dl><dt>번역</dt><dd>${x.translation}</dd><dt>선택 → 정답</dt><dd>${esc(x.selected??'미응답')} → <strong>${esc(x.correct)}</strong></dd><dt>접속·의미</dt><dd>${x.connection}</dd><dt>함정</dt><dd>${x.trap}</dd><dt>유사 문형</dt><dd>${x.similar}</dd><dt>예문</dt><dd>${x.example}</dd><dt>복습일</dt><dd>D+1 2026-08-31 · D+3 2026-09-02 · D+7 2026-09-06</dd><dt>다음번 풀이 절차</dt><dd>문장 끝의 평가 방향을 먼저 확인하고, 접속 형태로 선택지를 줄인 뒤 남은 문형의 의미를 대입하세요.</dd><dt>정답 직전 체크</dt><dd>접속 → 앞뒤 관계 → 문장 전체의 긍정·부정 방향을 차례로 확인하세요.</dd></dl></article>`).join('')}</section></main>`;return}
 const q=questions[current],all=[...q.choices,unknown];app.innerHTML=`<main class="shell"><header class="quiz-head"><div><p class="kicker">JLPT N2 · 文法 009〜015</p><strong>問題 ${current+1} / 10</strong></div><div class="timer ${elapsed>540?'danger':''}">${time()}</div></header><div class="progress"><i style="width:${(current+1)*10}%"></i></div><section class="question-card card"><div class="question-meta"><span>${q.kind}</span><span>問題 ${q.number}</span></div><h1>${esc(q.prompt)}</h1><div class="choices">${all.map((c,i)=>`<button class="${answers[q.id]===c?'selected':''}" onclick='pick(${JSON.stringify(c)})'><b>${i<4?i+1:'?'}</b><span>${esc(c)}</span></button>`).join('')}</div></section><nav><button class="secondary" ${current===0?'disabled':''} onclick="go(${current-1})">前へ</button><div class="dots">${questions.map((x,i)=>`<button class="${i===current?'active':''} ${answers[x.id]?'answered':''}" onclick="go(${i})">${i+1}</button>`).join('')}</div>${current<9?`<button class="primary" onclick="go(${current+1})">次へ</button>`:`<button class="primary" onclick="submit()">提出する</button>`}</nav></main>`
}
render();
</script></body></html>'''

out = root / "public" / "n2-grammar-009-015-check.html"
out.write_text(head + question_js + tail, encoding="utf-8")
print(out)
